// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAnalytics Throughput, quality, time and plan statistics for a period
	// (GET /analytics)
	GetAnalytics(w http.ResponseWriter, r *http.Request, params GetAnalyticsParams)
	// UploadAttachment Upload a file to attach to a task, an answer or a retry note
	// (POST /attachments)
	UploadAttachment(w http.ResponseWriter, r *http.Request)
	// DeleteAttachment Delete an upload that nothing uses yet
	// (DELETE /attachments/{id})
	DeleteAttachment(w http.ResponseWriter, r *http.Request, id int64)
	// GetAttachment An attached file's bytes
	// (GET /attachments/{id})
	GetAttachment(w http.ResponseWriter, r *http.Request, id int64)
	// Login Sign in with password and TOTP code
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetDashboard Everything the dashboard shows, in one call
	// (GET /dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request)
	// RegisterDevice Register this phone for push notifications (call again when the token changes)
	// (POST /devices)
	RegisterDevice(w http.ResponseWriter, r *http.Request)
	// UnregisterDevice Stop push notifications to this phone (on sign-out)
	// (POST /devices/unregister)
	UnregisterDevice(w http.ResponseWriter, r *http.Request)
	// GetPageDoc The "How this page works" text, as Markdown
	// (GET /docs/{page})
	GetPageDoc(w http.ResponseWriter, r *http.Request, page string, params GetPageDocParams)
	// ListEvents The global log, newest first, with filters and a cursor
	// (GET /events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// ExportEvents Download the log (last 90 days) as JSON lines or CSV
	// (GET /events/export)
	ExportEvents(w http.ResponseWriter, r *http.Request, params ExportEventsParams)
	// StreamEvents Server-Sent Events with every new event row (resume with Last-Event-ID)
	// (GET /events/stream)
	StreamEvents(w http.ResponseWriter, r *http.Request)
	// GetEventSummary Run statistics and time per step, for the Logs page
	// (GET /events/summary)
	GetEventSummary(w http.ResponseWriter, r *http.Request)

	// (GET /integrations)
	ListIntegrations(w http.ResponseWriter, r *http.Request)
	// SyncJira Pick up labelled Jira issues now
	// (POST /integrations/jira/sync)
	SyncJira(w http.ResponseWriter, r *http.Request)
	// ListPlaneStates States of the Plane projects linked to repositories, for the status mapping
	// (GET /integrations/plane/states)
	ListPlaneStates(w http.ResponseWriter, r *http.Request)
	// SyncPlane Pick up labelled Plane work items now
	// (POST /integrations/plane/sync)
	SyncPlane(w http.ResponseWriter, r *http.Request)
	// SetPlaneWebhookSecret Store the secret Plane generated for the agnts webhook
	// (PUT /integrations/plane/webhook-secret)
	SetPlaneWebhookSecret(w http.ResponseWriter, r *http.Request)
	// UpdateIntegration Change an integration's settings (never its token)
	// (PUT /integrations/{provider})
	UpdateIntegration(w http.ResponseWriter, r *http.Request, provider Provider)
	// ConnectIntegration Save a token (and settings), check it against the provider, and connect
	// (POST /integrations/{provider}/connect)
	ConnectIntegration(w http.ResponseWriter, r *http.Request, provider Provider)
	// DisconnectIntegration Forget the token
	// (POST /integrations/{provider}/disconnect)
	DisconnectIntegration(w http.ResponseWriter, r *http.Request, provider Provider)
	// ListRemoteRepos Repositories the connected GitHub or GitLab token can reach, for import
	// (GET /integrations/{provider}/repos)
	ListRemoteRepos(w http.ResponseWriter, r *http.Request, provider Provider)

	// (POST /integrations/{provider}/test)
	TestIntegration(w http.ResponseWriter, r *http.Request, provider Provider)
	// ListLessons Lessons agnts learned from pushed tickets, newest first
	// (GET /lessons)
	ListLessons(w http.ResponseWriter, r *http.Request, params ListLessonsParams)
	// GetLearnQueue Done tickets whose learn run is running, queued, failed or never happened
	// (GET /lessons/queue)
	GetLearnQueue(w http.ResponseWriter, r *http.Request)
	// GetLesson One lesson with its explanation, code references, quiz and reading
	// (GET /lessons/{id})
	GetLesson(w http.ResponseWriter, r *http.Request, id LessonID)
	// UnmarkLessonLearned Mark a lesson as not learned yet
	// (DELETE /lessons/{id}/learned)
	UnmarkLessonLearned(w http.ResponseWriter, r *http.Request, id LessonID)
	// MarkLessonLearned Mark a lesson learned
	// (PUT /lessons/{id}/learned)
	MarkLessonLearned(w http.ResponseWriter, r *http.Request, id LessonID)
	// GetMcpSettings The MCP connector URL and current connections
	// (GET /mcp-settings)
	GetMcpSettings(w http.ResponseWriter, r *http.Request)
	// RevokeMcp Disconnect every Claude connection and delete the static token
	// (POST /mcp-settings/revoke)
	RevokeMcp(w http.ResponseWriter, r *http.Request)
	// RotateMcpToken Create a new static MCP bearer token (shown once; the old one stops working)
	// (POST /mcp-settings/token)
	RotateMcpToken(w http.ResponseWriter, r *http.Request)
	// GetMeta Server version and build information
	// (GET /meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// GetConsent Details of a pending Claude connection request, for the consent page
	// (GET /oauth/consent)
	GetConsent(w http.ResponseWriter, r *http.Request, params GetConsentParams)
	// DecideConsent Approve or deny a Claude connection; returns where to send the browser
	// (POST /oauth/consent)
	DecideConsent(w http.ResponseWriter, r *http.Request)

	// (GET /repos)
	ListRepos(w http.ResponseWriter, r *http.Request)

	// (POST /repos)
	CreateRepo(w http.ResponseWriter, r *http.Request)
	// DetectRepo Work out a repository's toolchains and check commands
	// (POST /repos/detect)
	DetectRepo(w http.ResponseWriter, r *http.Request)

	// (GET /repos/{id})
	GetRepo(w http.ResponseWriter, r *http.Request, id RepoID)

	// (PUT /repos/{id})
	UpdateRepo(w http.ResponseWriter, r *http.Request, id RepoID)
	// ArchiveRepo Archive the repository; it keeps its history but takes no new tickets or tasks
	// (POST /repos/{id}/archive)
	ArchiveRepo(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoBranches Branches with their tip, ahead/behind the default branch and checks
	// (GET /repos/{id}/branches)
	ListRepoBranches(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoCommits Commits on the default branch, newest first, 50 per page; a shorter page is the last
	// (GET /repos/{id}/commits)
	ListRepoCommits(w http.ResponseWriter, r *http.Request, id RepoID, params ListRepoCommitsParams)
	// DeployRepo Start a deployment (GitLab manual job, or the GitHub deploy workflow). Never available from MCP.
	// (POST /repos/{id}/deploy)
	DeployRepo(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoEnvironments Deployment environments and what runs there
	// (GET /repos/{id}/environments)
	ListRepoEnvironments(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoLocalBranches Branches in agnts's own clones on the server, and whether origin has them
	// (GET /repos/{id}/local-branches)
	ListRepoLocalBranches(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoMembers People with access to the repository on its git host
	// (GET /repos/{id}/members)
	ListRepoMembers(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRepoPipelines CI runs with their stages, newest first, 20 per page; a shorter page is the last
	// (GET /repos/{id}/pipelines)
	ListRepoPipelines(w http.ResponseWriter, r *http.Request, id RepoID, params ListRepoPipelinesParams)
	// UnarchiveRepo Restore an archived repository
	// (POST /repos/{id}/unarchive)
	UnarchiveRepo(w http.ResponseWriter, r *http.Request, id RepoID)
	// ListRules Every rule, global ones first, then by repository
	// (GET /rules)
	ListRules(w http.ResponseWriter, r *http.Request)
	// CreateRule Add a rule; Claude reviews it before tickets follow it
	// (POST /rules)
	CreateRule(w http.ResponseWriter, r *http.Request)

	// (DELETE /rules/{id})
	DeleteRule(w http.ResponseWriter, r *http.Request, id RuleID)

	// (GET /rules/{id})
	GetRule(w http.ResponseWriter, r *http.Request, id RuleID)
	// UpdateRule Edit a rule. Changing its text or repository starts a new review; turning it on or off does not.
	// (PUT /rules/{id})
	UpdateRule(w http.ResponseWriter, r *http.Request, id RuleID)
	// AcceptRule Apply a rule as written, skipping its open questions or a failed review
	// (POST /rules/{id}/accept)
	AcceptRule(w http.ResponseWriter, r *http.Request, id RuleID)
	// AnswerRule Answer every open question of a rule; Claude then reviews it again
	// (PUT /rules/{id}/answers)
	AnswerRule(w http.ResponseWriter, r *http.Request, id RuleID)
	// ReviewRule Have Claude review a rule again, keeping its answers
	// (POST /rules/{id}/review)
	ReviewRule(w http.ResponseWriter, r *http.Request, id RuleID)

	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)

	// (PUT /settings)
	PutSettings(w http.ResponseWriter, r *http.Request)
	// CreateTask Create a side-project task
	// (POST /tasks)
	CreateTask(w http.ResponseWriter, r *http.Request)
	// DeleteTask Delete a task that has not started
	// (DELETE /tasks/{key})
	DeleteTask(w http.ResponseWriter, r *http.Request, key TicketKey)
	// UpdateTask Edit a task that has not started
	// (PATCH /tasks/{key})
	UpdateTask(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ListTickets Tickets, most recently active first
	// (GET /tickets)
	ListTickets(w http.ResponseWriter, r *http.Request, params ListTicketsParams)
	// GetTicket A ticket with its questions, analysis and latest result
	// (GET /tickets/{key})
	GetTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// StartTicket Start a held ticket now (it is queued for the next free slot)
	// (POST /tickets/{key}/analyze)
	StartTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// AnswerQuestions Answer the ticket's questions; when all are answered, coding starts
	// (PUT /tickets/{key}/answers)
	AnswerQuestions(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ApproveTicket Approve the reviewed work
	// (POST /tickets/{key}/approve)
	ApproveTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ListTicketEvents The ticket's log, oldest first; poll with `after` for live updates
	// (GET /tickets/{key}/events)
	ListTicketEvents(w http.ResponseWriter, r *http.Request, key TicketKey, params ListTicketEventsParams)
	// ListFollowUps Suggested follow-up tickets and the tickets made from them
	// (GET /tickets/{key}/follow-ups)
	ListFollowUps(w http.ResponseWriter, r *http.Request, key TicketKey)
	// SetFollowUps Turn follow-up suggestions on or off for this ticket
	// (PUT /tickets/{key}/follow-ups)
	SetFollowUps(w http.ResponseWriter, r *http.Request, key TicketKey)
	// AcceptFollowUps Create tickets from chosen suggestions
	// (POST /tickets/{key}/follow-ups/accept)
	AcceptFollowUps(w http.ResponseWriter, r *http.Request, key TicketKey)
	// DismissFollowUp Decline a suggestion; later runs will not suggest it again
	// (POST /tickets/{key}/follow-ups/{id}/dismiss)
	DismissFollowUp(w http.ResponseWriter, r *http.Request, key TicketKey, id int64)
	// ImplementTicket Make the code task that carries out a done plan or bug investigation
	// (POST /tickets/{key}/implement)
	ImplementTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// SetTicketKind Change what the ticket produces
	// (PUT /tickets/{key}/kind)
	SetTicketKind(w http.ResponseWriter, r *http.Request, key TicketKey)
	// LearnFromTicket Queue a learn run for a pushed ticket (again, if it already ran)
	// (POST /tickets/{key}/learn)
	LearnFromTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// MarkTicketMerged Record that a done ticket's pull request was merged
	// (POST /tickets/{key}/merged)
	MarkTicketMerged(w http.ResponseWriter, r *http.Request, key TicketKey)
	// SetTicketModels Override models for this ticket; omit a stage to use the default
	// (PUT /tickets/{key}/models)
	SetTicketModels(w http.ResponseWriter, r *http.Request, key TicketKey)
	// PreviewTicket Queue a preview (screenshots of the running app) of a ticket waiting for review, again if one already ran
	// (POST /tickets/{key}/preview)
	PreviewTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// GetPreviewShot One preview screenshot, as PNG
	// (GET /tickets/{key}/preview/{runId}/shots/{shotId})
	GetPreviewShot(w http.ResponseWriter, r *http.Request, key TicketKey, runId int64, shotId string)
	// RejectTicket Stop work on the ticket for good
	// (POST /tickets/{key}/reject)
	RejectTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ListRelations The ticket's ordering constraints and what holds it back now
	// (GET /tickets/{key}/relations)
	ListRelations(w http.ResponseWriter, r *http.Request, key TicketKey)
	// AddRelation Make this ticket wait for another, or keep the two from running side by side
	// (POST /tickets/{key}/relations)
	AddRelation(w http.ResponseWriter, r *http.Request, key TicketKey)
	// AcceptRelation Accept a relation agnts proposed; the queue follows it from now on
	// (POST /tickets/{key}/relations/{id}/accept)
	AcceptRelation(w http.ResponseWriter, r *http.Request, key TicketKey, id RelationID)
	// DismissRelation Dismiss a relation (run anyway); agnts does not propose it again
	// (POST /tickets/{key}/relations/{id}/dismiss)
	DismissRelation(w http.ResponseWriter, r *http.Request, key TicketKey, id RelationID)
	// SetTicketRepo Link the ticket to a repository
	// (PUT /tickets/{key}/repo)
	SetTicketRepo(w http.ResponseWriter, r *http.Request, key TicketKey)
	// RequestChanges Send the ticket back to coding with feedback
	// (POST /tickets/{key}/request-changes)
	RequestChanges(w http.ResponseWriter, r *http.Request, key TicketKey)
	// RetryTicket Resume a failed or rate-limited ticket where it stopped
	// (POST /tickets/{key}/retry)
	RetryTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// ReviewTicket Queue a code review of a ticket waiting for review (again, if one already ran)
	// (POST /tickets/{key}/review)
	ReviewTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// FollowUpFromFinding Turn a code review finding into a follow-up suggestion
	// (POST /tickets/{key}/review/findings/{index}/follow-up)
	FollowUpFromFinding(w http.ResponseWriter, r *http.Request, key TicketKey, index int)
	// StopTicket Stop the running stage; the ticket moves to failed and can be retried
	// (POST /tickets/{key}/stop)
	StopTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// TranslateTicket Translate a ticket's texts (its own and what agnts wrote) into a language
	// (POST /tickets/{key}/translate)
	TranslateTicket(w http.ResponseWriter, r *http.Request, key TicketKey)
	// GetUsage Plan usage from Claude Code's rate limit events
	// (GET /usage)
	GetUsage(w http.ResponseWriter, r *http.Request)
	// RefreshUsage Start a tiny Claude run to read fresh limits; a usage_updated event follows
	// (POST /usage/refresh)
	RefreshUsage(w http.ResponseWriter, r *http.Request)
	// GetTicketSpend Tickets that used the most of the plan in a period, by Claude Code's cost estimate
	// (GET /usage/tickets)
	GetTicketSpend(w http.ResponseWriter, r *http.Request, params GetTicketSpendParams)
}

